//! Working-tree reads and the untracked-file diff builder.
//!
//! Port of the file-reading helpers in `repo/gitCliHelpers.ts` and
//! `repo/gitCliRepo.ts:167-312`. The TS comments there explain the two non-obvious rules
//! this module keeps: a full-content preview must succeed on **both** sides or it is
//! dropped entirely (`gitCliRepo.ts:88`), and an untracked file's patch is generated by
//! hand instead of `git diff --no-index` because that output breaks the renderer on
//! Windows (`gitCliHelpers.ts:530`).

use std::path::{Path, PathBuf};
use std::sync::Arc;

use serde_json::{json, Value};

use crate::cmd::{GitCommand, GitCommandProvider, DIFF_BYTES, DIFF_TIMEOUT};
use crate::parse::StatusEntry;
use crate::path::normalize_git_path;

const UNTRACKED_STAT_MAX_BYTES: u64 = 1024 * 1024;
const UNTRACKED_STAT_CHUNK_BYTES: usize = 64 * 1024;
const UNTRACKED_STAT_CONCURRENCY: usize = 4;
pub const BINARY_DIFF_SUMMARY: &str = "Binary diff is not previewable.";

pub async fn file_exists(path: &Path) -> bool {
    tokio::fs::try_exists(path).await.unwrap_or(false)
}

/// `isPreviewableText` (`gitCliRepo.ts:167`).
pub fn is_previewable_text(content: &str) -> bool {
    !content.contains('\0')
}

/// `readWorkingTreePreviewContent` (`gitCliRepo.ts:171`). A failed `stat`/read must not be
/// reported as a legal empty file, otherwise the UI renders the whole file as added.
pub async fn read_working_tree_preview_content(absolute_path: &Path) -> Option<String> {
    let metadata = tokio::fs::metadata(absolute_path).await.ok()?;
    if !metadata.is_file() || metadata.len() > DIFF_BYTES as u64 {
        return None;
    }
    let content = tokio::fs::read(absolute_path).await.ok()?;
    let content = String::from_utf8_lossy(&content).into_owned();
    is_previewable_text(&content).then_some(content)
}

/// `readGitBlobPreviewContent` (`gitCliRepo.ts:186`).
pub async fn read_git_blob_preview_content(
    provider: &Arc<GitCommandProvider>,
    repo_root: &Path,
    reference: &str,
    repo_relative_path: &str,
) -> Option<String> {
    let spec = format!("{reference}:{repo_relative_path}");
    let result = provider
        .run(
            GitCommand::new(repo_root, &["show", &spec])
                .timeout(DIFF_TIMEOUT)
                .max_output_bytes(DIFF_BYTES),
        )
        .await
        .ok()?;
    if result.timed_out || result.output_truncated || result.exit_code != Some(0) {
        return None;
    }
    is_previewable_text(&result.stdout).then_some(result.stdout)
}

pub struct DiffContents {
    pub before: String,
    pub after: String,
}

/// `toCompleteDiffContents` (`gitCliRepo.ts:88`).
pub fn to_complete_diff_contents(
    before: Option<String>,
    after: Option<String>,
) -> Option<DiffContents> {
    Some(DiffContents {
        before: before?,
        after: after?,
    })
}

/// `withDiffContents` (`gitCliRepo.ts:297`): a successful patch is never discarded just
/// because the full-content preview failed.
pub fn with_diff_contents(mut diff: Value, contents: Option<DiffContents>) -> Value {
    if diff["availability"] != json!("patch") {
        return diff;
    }
    let Some(contents) = contents else {
        return diff;
    };
    diff["beforeContent"] = Value::String(contents.before);
    diff["afterContent"] = Value::String(contents.after);
    diff
}

/// `countUntrackedFileLines` (`gitCliHelpers.ts:427`). Returns `0` for directories,
/// oversized files, binary content and files that grow past the budget while reading.
async fn count_untracked_file_lines(absolute_path: &Path) -> i64 {
    let Ok(metadata) = tokio::fs::metadata(absolute_path).await else {
        return 0;
    };
    if !metadata.is_file() || metadata.len() > UNTRACKED_STAT_MAX_BYTES {
        return 0;
    }
    let Ok(mut file) = tokio::fs::File::open(absolute_path).await else {
        return 0;
    };
    let mut buffer = vec![0u8; UNTRACKED_STAT_CHUNK_BYTES];
    let mut total_bytes: u64 = 0;
    let mut newlines: i64 = 0;
    let mut last_byte: u8 = b'\n';
    loop {
        // The file can grow after `stat`; the read budget is enforced again per chunk and
        // one extra byte is only used to detect the overflow.
        let length = std::cmp::min(
            buffer.len() as u64,
            UNTRACKED_STAT_MAX_BYTES + 1 - total_bytes,
        ) as usize;
        let Ok(read) = tokio::io::AsyncReadExt::read(&mut file, &mut buffer[..length]).await else {
            return 0;
        };
        if read == 0 {
            return newlines + i64::from(last_byte != b'\n');
        }
        total_bytes += read as u64;
        if total_bytes > UNTRACKED_STAT_MAX_BYTES {
            return 0;
        }
        for byte in &buffer[..read] {
            if *byte == 0 {
                return 0;
            }
            if *byte == b'\n' {
                newlines += 1;
            }
        }
        last_byte = buffer[read - 1];
    }
}

/// `buildUntrackedStats` (`gitCliHelpers.ts:455`): bounded workers so a repository with
/// thousands of untracked files does not allocate them all at once.
pub async fn build_untracked_stats(
    repo_root: &Path,
    entries: &[StatusEntry],
) -> Vec<(String, i64)> {
    let untracked: Vec<&StatusEntry> = entries.iter().filter(|entry| entry.is_untracked).collect();
    if untracked.is_empty() {
        return Vec::new();
    }
    let mut tasks = Vec::new();
    for shard in untracked.chunks(untracked.len().div_ceil(UNTRACKED_STAT_CONCURRENCY)) {
        let owned: Vec<(String, PathBuf)> = shard
            .iter()
            .map(|entry| {
                (
                    entry.path.clone(),
                    crate::path::repo_relative_to_absolute(
                        &repo_root.to_string_lossy(),
                        &entry.path,
                    )
                    .into(),
                )
            })
            .collect();
        tasks.push(tokio::spawn(async move {
            let mut stats = Vec::new();
            for (path, absolute) in owned {
                stats.push((path, count_untracked_file_lines(Path::new(&absolute)).await));
            }
            stats
        }));
    }
    let mut stats = Vec::new();
    for task in tasks {
        if let Ok(shard) = task.await {
            stats.extend(shard);
        }
    }
    stats
}

/// The summary text `buildUntrackedTextDiffResult` uses for binary files
/// (`gitCliHelpers.ts:541`: "Binary diff is not previewable.").
const UNAVAILABLE_SUMMARY_BINARY: &str = "Binary diff is not previewable.";

/// `splitUntrackedText` (`gitCliHelpers.ts:498`).
fn split_untracked_text(content: &str) -> (Vec<&str>, bool) {
    if content.is_empty() {
        return (Vec::new(), false);
    }
    let has_trailing_newline = content.ends_with('\n');
    let raw: Vec<&str> = content.split('\n').collect();
    let total = raw.len();
    // Equivalent to TS's replace("\r\n", "\n"): strip only a \r immediately followed by \n (i.e. not the last segment,
    // or the last segment when the content itself ends with \n). The returned lines borrow the input lifetime, not a local owned value.
    let mut lines: Vec<&str> = raw
        .into_iter()
        .enumerate()
        .map(|(index, line)| {
            let followed_by_newline = index + 1 < total || has_trailing_newline;
            if followed_by_newline {
                line.strip_suffix('\r').unwrap_or(line)
            } else {
                line
            }
        })
        .collect();
    if has_trailing_newline {
        lines.pop();
    }
    (lines, has_trailing_newline)
}

/// `buildUntrackedTextDiffResult` (`gitCliHelpers.ts:522`).
pub async fn build_untracked_text_diff_result(
    absolute_path: &Path,
    repo_relative_path: &str,
    max_preview_bytes: usize,
) -> Option<Value> {
    let content = tokio::fs::read(absolute_path).await.ok()?;
    if content.contains(&0) {
        return Some(json!({
            "path": absolute_path.to_string_lossy(),
            "availability": "binary",
            "patch": Value::Null,
            "beforeContent": Value::Null,
            "afterContent": Value::Null,
            "summary": UNAVAILABLE_SUMMARY_BINARY,
        }));
    }
    if content.len() > max_preview_bytes {
        return Some(json!({
            "path": absolute_path.to_string_lossy(),
            "availability": "truncated",
            "patch": Value::Null,
            "beforeContent": Value::Null,
            "afterContent": Value::Null,
            "summary": "Git diff output exceeded the preview limit.",
        }));
    }
    let text = String::from_utf8_lossy(&content).into_owned();
    let normalized_path = normalize_git_path(repo_relative_path);
    let (lines, has_trailing_newline) = split_untracked_text(&text);
    let mut patch_lines = vec![
        "--- /dev/null".to_string(),
        format!("+++ b/{normalized_path}"),
    ];
    if !lines.is_empty() {
        patch_lines.push(format!("@@ -0,0 +1,{} @@", lines.len()));
        patch_lines.extend(lines.iter().map(|line| format!("+{line}")));
        if !has_trailing_newline {
            patch_lines.push("\\ No newline at end of file".to_string());
        }
    }
    Some(json!({
        "path": absolute_path.to_string_lossy(),
        "availability": "patch",
        "patch": format!("{}\n", patch_lines.join("\n")),
        "beforeContent": "",
        "afterContent": text,
        "summary": Value::Null,
    }))
}

/// Used by the untracked `--no-index` fallback (`gitCliRepo.ts:1351-1364`).
pub fn null_device_path() -> &'static str {
    if cfg!(windows) {
        "NUL"
    } else {
        "/dev/null"
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn split_untracked_text_tracks_the_final_newline() {
        assert_eq!(split_untracked_text(""), (Vec::new(), false));
        assert_eq!(split_untracked_text("a\nb\n"), (vec!["a", "b"], true));
        assert_eq!(split_untracked_text("a\r\nb"), (vec!["a", "b"], false));
    }

    #[test]
    fn complete_contents_requires_both_sides() {
        assert!(to_complete_diff_contents(Some("a".into()), None).is_none());
        assert!(to_complete_diff_contents(None, Some("b".into())).is_none());
        assert!(to_complete_diff_contents(Some("a".into()), Some("b".into())).is_some());
    }

    #[test]
    fn patch_survives_a_failed_preview() {
        let patch = json!({"availability": "patch", "beforeContent": Value::Null, "afterContent": Value::Null});
        let kept = with_diff_contents(patch.clone(), None);
        assert_eq!(kept["beforeContent"], Value::Null);
        let filled = with_diff_contents(
            patch,
            Some(DiffContents {
                before: "old".to_string(),
                after: "new".to_string(),
            }),
        );
        assert_eq!(filled["beforeContent"], json!("old"));
        assert_eq!(filled["afterContent"], json!("new"));
        let unavailable = json!({"availability": "unavailable"});
        let untouched = with_diff_contents(
            unavailable,
            Some(DiffContents {
                before: "x".to_string(),
                after: "y".to_string(),
            }),
        );
        assert_eq!(untouched["availability"], json!("unavailable"));
        assert!(untouched.get("beforeContent").is_none());
    }

    #[tokio::test]
    async fn untracked_text_diff_matches_the_ts_patch_shape() {
        let dir = std::env::temp_dir().join(format!("zcode-git-untracked-{}", std::process::id()));
        tokio::fs::create_dir_all(&dir).await.expect("dir");
        let file = dir.join("new.txt");
        tokio::fs::write(&file, "alpha\nbeta").await.expect("write");
        let diff = build_untracked_text_diff_result(&file, "new.txt", DIFF_BYTES)
            .await
            .expect("diff");
        assert_eq!(diff["availability"], json!("patch"));
        assert_eq!(
            diff["patch"],
            json!("--- /dev/null\n+++ b/new.txt\n@@ -0,0 +1,2 @@\n+alpha\n+beta\n\\ No newline at end of file\n")
        );
        assert_eq!(diff["beforeContent"], json!(""));
        assert_eq!(diff["afterContent"], json!("alpha\nbeta"));
        assert_eq!(diff["summary"], Value::Null);

        let binary = dir.join("bin.dat");
        tokio::fs::write(&binary, [1u8, 0, 2]).await.expect("write");
        let diff = build_untracked_text_diff_result(&binary, "bin.dat", DIFF_BYTES)
            .await
            .expect("diff");
        assert_eq!(diff["availability"], json!("binary"));
        assert_eq!(diff["summary"], json!("Binary diff is not previewable."));

        let empty = dir.join("empty.txt");
        tokio::fs::write(&empty, "").await.expect("write");
        let diff = build_untracked_text_diff_result(&empty, "empty.txt", DIFF_BYTES)
            .await
            .expect("diff");
        assert_eq!(diff["patch"], json!("--- /dev/null\n+++ b/empty.txt\n"));
        tokio::fs::remove_dir_all(&dir).await.ok();
    }

    #[tokio::test]
    async fn untracked_line_stats_count_newlines_and_respect_the_budget() {
        let dir = std::env::temp_dir().join(format!("zcode-git-stats-{}", std::process::id()));
        tokio::fs::create_dir_all(dir.join("nested"))
            .await
            .expect("dir");
        tokio::fs::write(dir.join("three.txt"), "a\nb\nc\n")
            .await
            .expect("write");
        tokio::fs::write(dir.join("noeol.txt"), "a\nb")
            .await
            .expect("write");
        let entries = vec![
            StatusEntry {
                path: "three.txt".to_string(),
                original_path: None,
                kind: crate::parse::KIND_ADDED,
                x: None,
                y: Some("?".to_string()),
                is_untracked: true,
                is_conflicted: false,
            },
            StatusEntry {
                path: "noeol.txt".to_string(),
                original_path: None,
                kind: crate::parse::KIND_ADDED,
                x: None,
                y: Some("?".to_string()),
                is_untracked: true,
                is_conflicted: false,
            },
            StatusEntry {
                // A collapsed untracked directory records `nested/`.
                path: "nested/".to_string(),
                original_path: None,
                kind: crate::parse::KIND_ADDED,
                x: None,
                y: Some("?".to_string()),
                is_untracked: true,
                is_conflicted: false,
            },
        ];
        let stats = build_untracked_stats(&dir, &entries).await;
        let lookup = |path: &str| {
            stats
                .iter()
                .find(|(key, _)| key == path)
                .map(|(_, added)| *added)
        };
        assert_eq!(lookup("three.txt"), Some(3));
        assert_eq!(lookup("noeol.txt"), Some(2));
        assert_eq!(lookup("nested/"), Some(0));
        tokio::fs::remove_dir_all(&dir).await.ok();
    }
}
